"""
MESSIBOOT — Asistente flotante del PRODE FIFA WORLD CUP 2026
==============================================================
Widget de chat flotante (burbuja abajo a la derecha, visible en todo
el sitio) que responde EXCLUSIVAMENTE sobre el sitio y el prode,
usando datos reales de Supabase (partidos, resultados, ranking,
pronósticos) y la API gratuita de Groq (Llama 3.3 70B) como motor.

ARQUITECTURA — por qué NO usa components.html:
Los componentes custom de Streamlit (components.html) corren dentro de
un <iframe sandboxed>. Ese sandbox bloquea explícitamente cualquier
intento del iframe de navegar a la página padre (window.parent.location,
formularios target="_parent", etc. — todo queda bloqueado igual con el
error "Unsafe attempt to initiate navigation... sandboxed, and is
therefore disallowed from navigating its ancestors"). Por eso este
widget usa SOLO st.markdown para la parte visual (vive en el DOM
principal, sin iframe, sin sandbox) y widgets nativos de Streamlit
(st.text_input / st.button) para la interacción real — esos sí pueden
disparar un rerun de verdad porque no están sandboxeados.

USO — pegar esta única línea al inicio de app.py y de cada página
en pages/, después de los imports de Streamlit:

    from messiboot import render_messiboot; render_messiboot()

CONFIGURACIÓN — definir la API key de Groq en .streamlit/secrets.toml:

    GROQ_API_KEY = "gsk_xxxxxxxxxxxxxxxxxxxxxxxx"

(o como variable de entorno GROQ_API_KEY). Se consigue gratis en
https://console.groq.com/keys
"""
import json
import streamlit as st
from database import conectar
from ranking import obtener_ranking

GROQ_MODEL = "llama-3.1-8b-instant"   # ✅ FIX: modelo liviano, límite 500x mayor
GROQ_URL = "https://api.groq.com/openai/v1/chat/completions"
HIST_KEY = "messiboot_historial"
OPEN_KEY = "messiboot_abierto"


# ──────────────────────────────────────────────────────────────────────────
# 1. Recolección de datos reales del prode (Supabase)
# ──────────────────────────────────────────────────────────────────────────
@st.cache_data(ttl=120, show_spinner=False)
def _obtener_contexto_prode() -> str:
    """
    Arma un resumen compacto y actualizado del estado real del prode:
    reglas de puntaje, fixture/resultados, ranking y participantes.
    Delega el cálculo de puntajes a obtener_ranking() (ranking.py + scoring.py)
    para mantener una única fuente de verdad.
    Se cachea 2 minutos para no saturar Supabase en cada mensaje.
    """
    try:
        sb = conectar()
    except Exception as e:
        return f"(No se pudo conectar a la base de datos: {e})"

    partes = [
        "REGLAS DEL PRODE:\n"
        "- Cada participante pronostica el signo (1 = gana local, "
        "X = empate, 2 = gana visitante) de cada partido del Mundial.\n"
        "- Acertar el signo exacto otorga 3 puntos.\n"
        "- No se otorgan puntos por marcador exacto, solo por signo (1/X/2)."
    ]

    try:
        # ── Ranking: fuente única de verdad (ranking.py → scoring.py) ──────
        ranking_data = obtener_ranking()  # [(nombre, puntos, aciertos, disputados), ...]

        if ranking_data:
            ranking_txt = "\n".join(
                f"{i+1}. {nombre} — {puntos} pts ({aciertos}/{disputados} aciertos)"
                for i, (nombre, puntos, aciertos, disputados) in enumerate(ranking_data)
            )
            partes.append(f"RANKING ACTUAL (de mayor a menor puntaje):\n{ranking_txt}")

            nombres_unicos = [nombre for nombre, *_ in ranking_data]
            partes.append(
                f"LISTADO DE PARTICIPANTES ({len(nombres_unicos)} en total):\n"
                + "\n".join(f"- {n}" for n in sorted(nombres_unicos))
            )
        else:
            partes.append("RANKING ACTUAL: todavía no hay participantes o pronósticos cargados.")
            nombres_unicos = []

        # ── Fixture: solo 1 query, sin recalcular puntajes ─────────────────
        partidos = sb.table("partidos").select(
            "id, grupo, fecha, hora, sede, local, visitante, resultado"
        ).execute().data or []

        jugados = [p for p in partidos if p.get("resultado")]
        pendientes = [p for p in partidos if not p.get("resultado")]

        def _label(p):
            r = p["resultado"]
            if r == "1":
                return f"Gana {p['local']}"
            if r == "2":
                return f"Gana {p['visitante']}"
            return "Empate"

        if jugados:
            jugados_txt = "\n".join(
                f"- Grupo {p['grupo']}: {p['local']} vs {p['visitante']} "
                f"({p['fecha']}) → resultado: {_label(p)}"
                for p in jugados
            )
            partes.append(f"PARTIDOS YA JUGADOS:\n{jugados_txt}")

        if pendientes:
            pendientes_txt = "\n".join(
                f"- Grupo {p['grupo']}: {p['local']} vs {p['visitante']} "
                f"el {p['fecha']} {p.get('hora', '')} en {p.get('sede', '')}"
                for p in pendientes
            )
            partes.append(f"PARTIDOS PENDIENTES (sin jugar):\n{pendientes_txt}")

        partes.append(
            f"TOTAL: {len(nombres_unicos)} participantes únicos, {len(partidos)} partidos "
            f"({len(jugados)} jugados, {len(pendientes)} pendientes)."
        )

    except Exception as e:
        partes.append(f"(Aviso: no se pudieron cargar todos los datos en vivo: {e})")

    return "\n\n".join(partes)



# ──────────────────────────────────────────────────────────────────────────
# 2. Comparación de boletas (misma lógica que 08_Comparar_Boletas.py)
# ──────────────────────────────────────────────────────────────────────────
@st.cache_data(ttl=120, show_spinner=False)
def _datos_comparacion() -> tuple:
    """
    Descarga participantes, partidos y pronósticos una sola vez (cacheado 2 min).
    Retorna (part_nombre, pron_por_partido, partidos_raw) en el mismo formato
    que usa 08_Comparar_Boletas.py.
    """
    try:
        sb = conectar()

        def fetch_all(table, columns, order_cols=None, page_size=1000):
            rows, start = [], 0
            while True:
                query = sb.table(table).select(columns)
                if order_cols:
                    for col in order_cols:
                        query = query.order(col)
                chunk = query.range(start, start + page_size - 1).execute().data or []
                rows.extend(chunk)
                if len(chunk) < page_size:
                    break
                start += page_size
            return rows

        participantes_raw = fetch_all("participantes", "id, nombre", order_cols=["nombre"])
        partidos_raw      = fetch_all("partidos", "*", order_cols=["grupo", "fecha", "hora"])
        pronosticos_raw   = fetch_all("pronosticos", "participante_id, partido_id, pronostico")

        part_nombre = {str(p["id"]): p["nombre"] for p in participantes_raw}

        pron_por_partido = {}
        for pr in pronosticos_raw:
            pid = str(pr["partido_id"])
            uid = str(pr["participante_id"])
            pron_por_partido.setdefault(pid, {})[uid] = pr["pronostico"]

        return part_nombre, pron_por_partido, partidos_raw
    except Exception:
        return {}, {}, []


def _detectar_comparacion(pregunta: str, part_nombre: dict) -> tuple:
    """
    Detecta si la pregunta pide comparar boletas entre dos participantes.
    Busca palabras clave de comparacion y dos nombres en el texto.
    Retorna (nombre1, nombre2) o (None, None) si no detecta comparacion.
    """
    palabras_clave = ["compara", "comparar", "boleta", "pronostico", "pronosticos",
                      "vs", "versus", "contra", "diferencia", "coinciden", "igual"]
    pregunta_lower = pregunta.lower()

    if not any(p in pregunta_lower for p in palabras_clave):
        return None, None

    nombres = list(part_nombre.values())
    encontrados = [
        n for n in nombres
        if any(parte.lower() in pregunta_lower for parte in n.split() if len(parte) > 3)
    ]
    if len(encontrados) >= 2:
        return encontrados[0], encontrados[1]
    return None, None


def _comparar_boletas_texto(nombre1: str, nombre2: str) -> str:
    """
    Compara las boletas de dos participantes y devuelve un resumen en texto
    listo para enviar al LLM como contexto adicional.
    """
    part_nombre, pron_por_partido, partidos_raw = _datos_comparacion()

    nombre_a_id = {v: k for k, v in part_nombre.items()}

    def buscar_id(nombre_buscado):
        if nombre_buscado in nombre_a_id:
            return nombre_a_id[nombre_buscado]
        for nombre, pid in nombre_a_id.items():
            if any(parte.lower() in nombre.lower() for parte in nombre_buscado.split() if len(parte) > 3):
                return pid
        return None

    id1 = buscar_id(nombre1)
    id2 = buscar_id(nombre2)

    if not id1 or not id2:
        faltantes = []
        if not id1:
            faltantes.append(nombre1)
        if not id2:
            faltantes.append(nombre2)
        return f"No encontre en el prode a: {', '.join(faltantes)}."

    n1_real = part_nombre.get(id1, nombre1)
    n2_real = part_nombre.get(id2, nombre2)

    labels_r = {"1": "Gana local", "X": "Empate", "2": "Gana visitante"}

    coinciden, difieren, sin_comparar = [], [], []

    for p in partidos_raw:
        pid_str   = str(p["id"])
        local     = p["local"]
        visitante = p["visitante"]
        resultado = p.get("resultado") or ""
        apuestas  = pron_por_partido.get(pid_str, {})
        v1 = apuestas.get(id1)
        v2 = apuestas.get(id2)
        partido_label = f"{local} vs {visitante}"
        res_label = f" [resultado: {labels_r.get(resultado, resultado)}]" if resultado else ""

        if v1 is None or v2 is None:
            sin_comparar.append(partido_label)
        elif v1 == v2:
            coinciden.append(f"{partido_label}: ambos pusieron {v1} ({labels_r.get(v1,v1)}){res_label}")
        else:
            difieren.append(
                f"{partido_label}: {n1_real} puso {v1} ({labels_r.get(v1,v1)}) — "
                f"{n2_real} puso {v2} ({labels_r.get(v2,v2)}){res_label}"
            )

    lineas = [
        f"COMPARACION DE BOLETAS: {n1_real} vs {n2_real}",
        f"Resumen: {len(coinciden)} coincidencias, {len(difieren)} diferencias, {len(sin_comparar)} sin comparar.",
        "",
    ]
    if coinciden:
        lineas.append("PARTIDOS QUE COINCIDEN:")
        lineas.extend(f"  - {c}" for c in coinciden)
        lineas.append("")
    if difieren:
        lineas.append("PARTIDOS QUE DIFIEREN:")
        lineas.extend(f"  - {d}" for d in difieren)

    return "\n".join(lineas)



def _detectar_aciertos(pregunta: str, part_nombre: dict) -> str | None:
    """
    Detecta si la pregunta pide ver los aciertos/errores de UN participante.
    Retorna el nombre encontrado o None.
    """
    palabras_clave = ["acerto", "acerto", "acerto", "acerto", "acerto",
                      "acerto", "acerto", "fallo", "fallo", "fallaste",
                      "no acerto", "no acerto", "acierto", "aciertos",
                      "errores", "error", "equivoco", "equivoco",
                      "que puso", "como le fue", "como va", "cuantos acerto",
                      "cuantos aciertos", "que aciertos", "que fallo",
                      "partidos acerto", "partidos fallo", "boleta de"]
    pregunta_lower = pregunta.lower()

    # Descartar si son DOS participantes (eso es comparacion)
    nombres = list(part_nombre.values())
    encontrados = [
        n for n in nombres
        if any(parte.lower() in pregunta_lower for parte in n.split() if len(parte) > 3)
    ]
    if len(encontrados) >= 2:
        return None  # es comparacion, no aciertos

    if not any(p in pregunta_lower for p in palabras_clave):
        return None

    if len(encontrados) == 1:
        return encontrados[0]
    return None


def _detalle_aciertos_texto(nombre: str) -> str:
    """
    Devuelve un desglose partido por partido de lo que acerto y fallo
    un participante, usando los datos reales de Supabase.
    """
    part_nombre, pron_por_partido, partidos_raw = _datos_comparacion()

    nombre_a_id = {v: k for k, v in part_nombre.items()}

    def buscar_id(nombre_buscado):
        if nombre_buscado in nombre_a_id:
            return nombre_a_id[nombre_buscado]
        for nombre_bd, pid in nombre_a_id.items():
            if any(parte.lower() in nombre_bd.lower() for parte in nombre_buscado.split() if len(parte) > 3):
                return pid
        return None

    pid = buscar_id(nombre)
    if not pid:
        return f"No encontre al participante '{nombre}' en el prode."

    nombre_real = part_nombre.get(pid, nombre)
    labels_r = {"1": "Gana local", "X": "Empate", "2": "Gana visitante"}

    aciertos, errores, pendientes = [], [], []

    for p in partidos_raw:
        pid_str   = str(p["id"])
        local     = p["local"]
        visitante = p["visitante"]
        resultado = p.get("resultado") or ""
        pronostico = pron_por_partido.get(pid_str, {}).get(pid)
        partido_label = f"{local} vs {visitante}"

        if not resultado:
            if pronostico:
                pendientes.append(f"{partido_label}: pronostico {pronostico} ({labels_r.get(pronostico, pronostico)})")
            else:
                pendientes.append(f"{partido_label}: sin pronostico")
            continue

        if pronostico is None:
            errores.append(f"{partido_label}: sin pronostico [resultado: {labels_r.get(resultado, resultado)}]")
        elif pronostico == resultado:
            aciertos.append(
                f"{partido_label}: puso {pronostico} ({labels_r.get(pronostico,pronostico)}) - CORRECTO"
            )
        else:
            errores.append(
                f"{partido_label}: puso {pronostico} ({labels_r.get(pronostico,pronostico)}) "
                f"pero fue {resultado} ({labels_r.get(resultado,resultado)})"
            )

    lineas = [
        f"DETALLE DE ACIERTOS DE {nombre_real}:",
        f"Aciertos: {len(aciertos)} | Errores: {len(errores)} | Pendientes: {len(pendientes)}",
        "",
    ]
    if aciertos:
        lineas.append("ACERTO:")
        lineas.extend(f"  + {a}" for a in aciertos)
        lineas.append("")
    if errores:
        lineas.append("FALLO:")
        lineas.extend(f"  x {e}" for e in errores)
        lineas.append("")
    if pendientes:
        lineas.append("PENDIENTES (sin jugar):")
        lineas.extend(f"  ? {p}" for p in pendientes)

    return "\n".join(lineas)


# ──────────────────────────────────────────────────────────────────────────
# 2. Llamada a Groq
# ──────────────────────────────────────────────────────────────────────────
def _groq_api_key() -> str:
    import os
    key = os.environ.get("GROQ_API_KEY", "")
    if not key:
        try:
            key = st.secrets.get("GROQ_API_KEY", "")
        except Exception:
            pass
    return key


def _buscar_participante_en_contexto(pregunta: str, nombres_unicos: list) -> str:
    """
    Busca si la pregunta menciona un participante por apellido o nombre parcial.
    Devuelve un hint extra para el system prompt si encuentra coincidencias.
    """
    pregunta_lower = pregunta.lower()
    coincidencias = [
        n for n in nombres_unicos
        if any(parte.lower() in pregunta_lower for parte in n.split() if len(parte) > 3)
    ]
    if coincidencias:
        return f"\nNOTA: La pregunta parece referirse a: {', '.join(coincidencias)}. Buscá estos nombres exactos en el ranking y listado."
    return ""


def _llamar_groq(pregunta: str, contexto: str) -> str:
    import urllib.request
    import urllib.error

    api_key = _groq_api_key()
    if not api_key:
        return (
            "⚠️ Falta configurar GROQ_API_KEY en .streamlit/secrets.toml "
            "(conseguila gratis en console.groq.com/keys)."
        )

    system_prompt = (
        "Sos MessiBoot, el asistente virtual oficial del sitio PRODE FIFA WORLD CUP 2026. "
        "SOLO podés hablar de este sitio y del prode: reglas, puntajes, ranking, partidos, "
        "resultados, pronósticos y participantes. Si te preguntan algo que no tiene que ver "
        "con el sitio o el prode, respondé amablemente que solo podés ayudar con temas del "
        "prode.\n\n"
        "INSTRUCCIONES CRÍTICAS PARA BUSCAR NOMBRES:\n"
        "- Cuando te pregunten por una persona, buscá su nombre en el LISTADO DE PARTICIPANTES "
        "y en el RANKING usando búsqueda APROXIMADA e INSENSIBLE A MAYÚSCULAS/MINÚSCULAS.\n"
        "- Si alguien pregunta por 'Leo Sagrista', buscá también 'Leonardo Sagrista', "
        "'L. Sagrista', etc. Usá el apellido como clave principal de búsqueda.\n"
        "- Si el nombre aparece en el LISTADO DE PARTICIPANTES, la persona SÍ participa en "
        "el prode, aunque no tenga puntos todavía (0 pts es válido).\n"
        "- NUNCA digas que alguien no existe si su apellido aparece en el listado.\n\n"
        "Usá los datos reales provistos abajo para responder con precisión, números "
        "exactos y nombres correctos. No inventes datos que no estén en el contexto. "
        "Sé breve, claro y con onda futbolera, podés usar algún emoji con "
        "moderación (⚽🏆📊). Respondé siempre en español.\n\n"
        "DATOS REALES Y ACTUALIZADOS DEL SITIO:\n" + contexto
    )

    payload = {
        "model": GROQ_MODEL,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": pregunta + _buscar_participante_en_contexto(pregunta, [l.replace("- ","") for l in contexto.split("\n") if l.startswith("- ") and len(l) > 5])},
        ],
        "temperature": 0.4,
        "max_tokens": 600,
    }

    req = urllib.request.Request(
        GROQ_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
            # Cloudflare (delante de la API de Groq) devuelve 403 / código
            # 1010 a requests sin un User-Agent de aspecto "normal" — lo
            # agregamos explícitamente porque urllib no manda uno por defecto.
            "User-Agent": "Mozilla/5.0 (compatible; MessiBootProde/1.0)",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        return data["choices"][0]["message"]["content"].strip()
    except urllib.error.HTTPError as e:
        detalle = e.read().decode("utf-8", errors="ignore")
        if e.code == 413 or "TPM" in detalle or "rate" in detalle.lower():
            return "Hay mucho tráfico en este momento ⚽ Esperá unos segundos y volvé a preguntar."
        return f"⚠️ Error de conexión ({e.code}). Avisale al admin del Prode."
    except Exception as e:
        return "No pude responder ahora mismo, intentá de nuevo en un momento ⚽"


